using System.Collections.ObjectModel;using Microsoft.Extensions.DependencyInjection;using Microsoft.UI.Xaml;using Microsoft.UI.Xaml.Controls;using UPM.Windows.SiteApi;
namespace UPM.SiteManager.Views;
public sealed partial class ReviewSessionsPage:Page{private readonly IOperatorContext context=App.Services.GetRequiredService<IOperatorContext>();private readonly ObservableCollection<ReviewRow> rows=[];private bool subscribed;public ReviewSessionsPage(){InitializeComponent();ReviewList.ItemsSource=rows;}private void OnLoaded(object s,RoutedEventArgs e){if(!subscribed){context.Changed+=OnChanged;subscribed=true;}_=RefreshAsync();}private void OnUnloaded(object s,RoutedEventArgs e){if(subscribed){context.Changed-=OnChanged;subscribed=false;}}private void OnChanged(object? s,OperatorContextChangedEventArgs e)=>DispatcherQueue.TryEnqueue(()=>_=RefreshAsync());private void OnRefresh(object s,RoutedEventArgs e)=>_=RefreshAsync();private async Task RefreshAsync(){rows.Clear();var api=context.ActiveClient;if(api is null){Show("Connect to a Site to view review sessions.",InfoBarSeverity.Informational);return;}try{var payload=await api.GetReviewSessionsAsync(CancellationToken.None);foreach(var x in payload.Items())rows.Add(new ReviewRow{Presentation=x.Text("presentation_title",x.Text("presentation_id")),BaseVersion="Base version "+x.Text("base_presentation_version_id"),Room=x.Text("room_label",x.Text("room_id")),Device=x.Text("device_name",x.Text("device_id")),State=x.Text("state").ToUpperInvariant(),Opened=JsonProjection.LocalTime(x.Text("opened_at","")),Changes=x.Text("local_changes_at","")==""?"No local changes":"Local changes "+JsonProjection.LocalTime(x.Text("local_changes_at","")),Saveback=x.Text("conflict_version_id","")!=""?"REVISION CONFLICT":x.Text("saveback_version_id","")!=""?"Saveback complete":"Saveback pending"});CountText.Text=$"{rows.Count} active and recent sessions";if(rows.Count==0)Show("No active review sessions.",InfoBarSeverity.Informational);else StateBar.IsOpen=false;}catch(Exception ex){Show(ex.Message,InfoBarSeverity.Error);}}private void Show(string m,InfoBarSeverity s){StateBar.Title=s==InfoBarSeverity.Error?"REVIEW API ERROR":"REVIEWS";StateBar.Message=m;StateBar.Severity=s;StateBar.IsOpen=true;}}
public sealed class ReviewRow{public string Presentation{get;set;}="";public string BaseVersion{get;set;}="";public string Room{get;set;}="";public string Device{get;set;}="";public string State{get;set;}="";public string Opened{get;set;}="";public string Changes{get;set;}="";public string Saveback{get;set;}="";}
